def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        r = props.get(e, {}).get('covalent_radius_A')
        if x is not None and x > 0 and r is not None and math.isfinite(r) and r > 0:
            total += x * r * r * r
            weight += x
    if weight <= 0:
        return 0.0
    return float(4.0 * math.pi * total / (3.0 * weight * v))

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    occ = [max(float(t.get('occupancy', 1.0) or 0.0), 0.0) for t in sites]
    nearest = [math.inf] * n
    for b in s.get('neighbors', ()):
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A')
        if 0 <= i < n and 0 <= j < n and occ[i] > 0 and occ[j] > 0 and d is not None and math.isfinite(d) and d > 0:
            nearest[i] = min(nearest[i], d)
    weight = sum(occ[i] for i in range(n) if math.isfinite(nearest[i]))
    if weight <= 0:
        return 0.0
    return float(sum(occ[i] * nearest[i] for i in range(n) if math.isfinite(nearest[i])) / weight)

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    props = s.get('element_properties', {})
    radii = [props.get(t.get('element'), {}).get('covalent_radius_A') for t in sites]
    occ = [max(float(t.get('occupancy', 1.0) or 0.0), 0.0) for t in sites]
    nearest = [math.inf] * n
    for b in s.get('neighbors', ()):
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A')
        if 0 <= i < n and 0 <= j < n and occ[i] > 0 and occ[j] > 0 and d is not None and math.isfinite(d) and d > 0:
            a = radii[i]
            c = radii[j]
            if a is not None and c is not None and math.isfinite(a) and math.isfinite(c) and a > 0 and c > 0:
                nearest[i] = min(nearest[i], d / (a + c))
    weight = sum(occ[i] for i in range(n) if math.isfinite(nearest[i]))
    if weight <= 0:
        return 0.0
    return float(sum(occ[i] * nearest[i] for i in range(n) if math.isfinite(nearest[i])) / weight)

def feature(s):
    sites = s.get('sites', ())
    n = len(sites)
    occ = [max(float(t.get('occupancy', 1.0) or 0.0), 0.0) for t in sites]
    nearest = [math.inf] * n
    for b in s.get('neighbors', ()):
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A')
        if 0 <= i < n and 0 <= j < n and occ[i] > 0 and occ[j] > 0 and d is not None and math.isfinite(d) and d > 0:
            nearest[i] = min(nearest[i], d)
    coordination = [0.0] * n
    for b in s.get('neighbors', ()):
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A')
        if 0 <= i < n and 0 <= j < n and math.isfinite(nearest[i]) and d is not None and math.isfinite(d) and 0 < d <= 1.5 * nearest[i]:
            coordination[i] += occ[j] * math.exp(1.0 - (d / nearest[i]) ** 6)
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    return float(sum(occ[i] * coordination[i] for i in range(n)) / weight)

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    weight = 0.0
    for e, x in s.get('composition', {}).items():
        z = props.get(e, {}).get('valence_electrons')
        if x is not None and x > 0 and z is not None and math.isfinite(z) and z >= 0:
            total += x * z
            weight += x
    return float(total / (weight * v)) if weight > 0 else 0.0

def feature(s):
    props = s.get('element_properties', {})
    entries = []
    for e, x in s.get('composition', {}).items():
        p = props.get(e, {})
        ion = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if x is not None and x > 0 and ion is not None and affinity is not None and math.isfinite(ion) and math.isfinite(affinity) and ion > 0 and ion - affinity > 0.000001:
            entries = entries + [(x, 0.5 * (ion + affinity), ion - affinity)]
    weight = sum(t[0] for t in entries)
    inverse_hardness = sum(t[0] / t[2] for t in entries)
    if weight <= 0 or inverse_hardness <= 0:
        return 0.0
    chemical_potential = sum(t[0] * t[1] / t[2] for t in entries) / inverse_hardness
    variance = sum(t[0] * ((chemical_potential - t[1]) / t[2]) ** 2 for t in entries) / weight
    return float(math.sqrt(max(variance, 0.0)))

def feature(s):
    composition = s.get('composition', {})
    props = s.get('element_properties', {})
    best = math.inf
    for donor, x in composition.items():
        ion = props.get(donor, {}).get('first_ionization_energy_eV')
        if x is not None and x > 0 and ion is not None and math.isfinite(ion) and ion > 0:
            for acceptor, y in composition.items():
                affinity = props.get(acceptor, {}).get('electron_affinity_eV')
                if donor != acceptor and y is not None and y > 0 and affinity is not None and math.isfinite(affinity):
                    best = min(best, ion - affinity)
    return float(best) if math.isfinite(best) else 0.0
